import{_ as i,o,a as t,b as e}from"./app.C41L12d5.js";const r="/ascendc.github.io/assets/mat_pos_65.DLlRWsms.png",n="/ascendc.github.io/assets/mat_pos_66.B1QxfD80.png",g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"算子实践参考","link":"/guide/operator_practice/document_structure"},{"text":"SIMD算子性能优化","link":"/guide/operator_practice/simd_operator_optimization/simd_operator_optimization"},{"text":"内存访问","link":"/guide/operator_practice/simd_operator_optimization/memory_access/memory_access"},{"text":"避免UB的bank冲突","link":"/guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/avoid_ub_bank_conflict"},{"text":"概述","link":"/guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/overview"}]},"headers":[],"relativePath":"guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/overview.md","filePath":"guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/overview.md","lastUpdated":1787218201000}'),_={name:"guide/operator_practice/simd_operator_optimization/memory_access/avoid_ub_bank_conflict/overview.md"};function p(s,a,c,l,m,d){return o(),t("div",null,[...a[0]||(a[0]=[e('<div><article class="markdown-body"><h1>概述<span id="ZH-CN_TOPIC_0000002534006769"></span></h1><p>【优先级】高</p><p>【概述】</p><p>为了提高数据访问的效率和吞吐量，Unified Buffer（UB）采用了大小相等的内存模块（bank）结构设计。当多条读写指令同时访问UB时，由于硬件资源的限制，这些指令不能同时执行，从而引发bank冲突。在这种情况下，指令需要排队等待资源，无法在一个指令周期内完成。</p><ul><li><p>针对<a href="../../../../programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本2201</a></p><p><img src="'+r+'" alt></p><p>UB总大小为192KB，包含16个bank group，每个bank group包含3个bank。每个bank大小为4KB，由128行组成，每行长度为32B。</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：多个读操作同时尝试访问同一个bank group。</li></ul></li><li><p>针对<a href="../../../../programming_guide/language_extension/simd_builtin_keywords.html#npu-arch">NPU架构版本3510</a></p><p><img src="'+n+'" alt></p><p>UB总大小为256KB，包含8个bank group，每个bank group包含2个bank。每个bank大小为16KB，由512行组成，每行长度为32B。</p><ul><li><strong>读写冲突</strong>：读操作和写操作同时尝试访问同一个bank。</li><li><strong>写写冲突</strong>：多个写操作同时尝试访问同一个bank group。</li><li><strong>读读冲突</strong>：两个读操作同时尝试访问同一个bank，或者两个以上读操作同时尝试访问同一个bank group。</li></ul></li></ul><p>可以看出bank冲突的场景与UB的规格密切相关，规格的变化通常会导致bank冲突场景的变化。</p><ul><li>NPU架构版本3510中，同一个bank group单拍支持两次读操作。因此，两次读操作访问同一个bank group的不同bank时，不会引起冲突；若两次读操作访问同一个bank，或者同一个bank group内发生两次以上读操作，则会引起冲突。</li><li>假设读指令操作的地址为0x0000（bank0），写指令操作的地址为0x10000 ，在NPU架构版本2201中，地址0x10000（bank16）不会发生读写冲突，而在NPU架构版本3510中，这个地址0x10000（bank0）会引发读写冲突。</li></ul><p>下文介绍不同硬件架构下如何避免bank冲突。</p></article></div>',1)])])}const b=i(_,[["render",p]]);export{g as __pageData,b as default};
